e']).' KM':'' ?></small></td><td><strong>♙ <?= e($row['customer_name']) ?></strong><small>♧ <?= e($row['contact_number']) ?></small></td><td><span class="job-summary-text"><?= e($row['complaint'] ?: ($row['requested_work'] ?: '-')) ?></span><small><?= (int)$row['item_count'] ?> item<?= (int)$row['item_count']===1?'':'s' ?> · <?= e($row['mechanic_name']?:'Mechanic not assigned') ?></small></td><td><span class="job-priority job-priority-<?= e($row['priority']) ?>"><?= ucfirst($row['priority']) ?></span></td><td><?= e(date('d M Y',strtotime($row['created_at']))) ?><small><?= e(date('h:i A',strtotime($row['created_at']))) ?></small></td><td><div class="job-row-actions"><a class="btn btn-light btn-sm" href="index.php?page=admin&amp;section=jobcards-view&amp;id=<?= (int)$row['id'] ?>">◉ View</a><?php if(in_array($status, ['pending', 'ongoing'], true)): ?><a class="btn btn-light btn-sm" href="index.php?page=admin&amp;section=jobcards-edit&amp;id=<?= (int)$row['id'] ?>">✎ Edit</a><form method="post" action="index.php?page=admin&amp;section=jobcards-delete" onsubmit="return confirm('Delete this job card? This action cannot be undone.');"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="job_card_id" value="<?= (int)$row['id'] ?>"><button class="btn btn-outline-danger btn-sm" type="submit">⌫ Delete</button></form><?php endif; ?><?php if($status==='pending'): ?><form method="post" action="index.php?page=admin&amp;section=jobcards-action"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="job_card_id" value="<?= (int)$row['id'] ?>"><input type="hidden" name="action" value="start"><button class="btn btn-primary btn-sm">▷ Start</button></form><?php endif; ?></div></td></tr><?php endforeach; endif; ?></tbody></table></div><div class="jobcard-list-footer"><span>Showing 1 to <?= count($rows) ?> of <?= count($rows) ?> job cards</span><div><button class="btn btn-light btn-sm" disabled>‹ Prev</